model User {
  id       Int       @id @default(autoincrement())
  projects Project[]
  auth     Auth?
}

model Project {
  id     Int    @id @default(autoincrement())
  name   String
  user   User   @relation(fields: [userId], references: [id])
  userId Int
  tasks  Task[]

  @@unique([userId, name])
}

